WITH flattened AS (SELECT id, host, latency_ms, status_code, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, attr_value) SELECT *, ROUND(status_code / SUM(status_code) OVER (PARTITION BY host), 4) AS status_code_share, PERCENT_RANK() OVER (ORDER BY status_code DESC) AS status_code_percent_rank, MIN(latency_ms) OVER (PARTITION BY host) AS host_min_latency_ms, CUME_DIST() OVER (PARTITION BY k, host ORDER BY status_code) AS status_code_cume_dist, RANK() OVER (PARTITION BY host ORDER BY status_code DESC) AS status_code_rank FROM flattened
